import pathlib
p = pathlib.Path('src/ir_lower/context.rs')
t = p.read_text()

# `load_local`'s own doc line was swallowed when this predicate was inserted above it.
old_doc = '''    /// Emits a load from a PHP local slot.
    /// Returns true when a read of `slot` is PHP's "undefined variable" case.'''
new_doc = '''    /// Returns true when a read of `slot` is PHP's "undefined variable" case.'''
assert t.count(old_doc) == 1
t = t.replace(old_doc, new_doc)

old_fn = '''    pub(crate) fn load_local(&mut self, name: &str, span: Option<Span>) -> LoweredValue {'''
new_fn = '''    /// Emits a load from a PHP local slot.
    pub(crate) fn load_local(&mut self, name: &str, span: Option<Span>) -> LoweredValue {'''
assert t.count(old_fn) == 1
t = t.replace(old_fn, new_fn)

old_gate = '''    /// Everything a frame RECEIVES rather than stores is excluded: globals resolve through their
    /// own symbol, a static local keeps its value across calls, a by-reference binding reads the
    /// caller's cell, and parameters are marked initialized by the prologue. Missing one of those
    /// would not crash — it would warn about a variable that is perfectly well defined.
    fn read_is_of_an_undefined_local(
        &self,
        slot: LocalSlotId,
        kind: LocalKind,
        uses_global: bool,
        is_ref_bound: bool,
    ) -> bool {
        self.probe_spine_depth == 0
            && !uses_global
            && !is_ref_bound
            && kind == LocalKind::PhpLocal
            && !self.slot_is_initialized(slot)
    }'''
new_gate = '''    /// Everything a frame RECEIVES rather than stores is excluded: globals resolve through their
    /// own symbol, a static local keeps its value across calls, a by-reference binding reads the
    /// caller's cell, and parameters are marked initialized by the prologue. Missing one of those
    /// would not crash — it would warn about a variable that is perfectly well defined.
    ///
    /// An `eval()` already lowered in this scope closes the question for everything after it: the
    /// fragment can bind any name, so no later read is DEFINITELY of an undefined variable. Both
    /// flags are consulted because the barrier-free AOT path records only `eval_executed`, and
    /// `eval('$c = 1;'); echo $c;` went through it — printing the warning and nothing else where
    /// PHP prints `1`. Position still decides: the flags are set as lowering reaches the `eval()`,
    /// so a read written BEFORE it still warns, exactly as PHP does.
    fn read_is_of_an_undefined_local(
        &self,
        slot: LocalSlotId,
        kind: LocalKind,
        uses_global: bool,
        is_ref_bound: bool,
    ) -> bool {
        self.probe_spine_depth == 0
            && !self.eval_barrier_active
            && !self.eval_executed
            && !uses_global
            && !is_ref_bound
            && kind == LocalKind::PhpLocal
            && !self.slot_is_initialized(slot)
    }'''
assert t.count(old_gate) == 1
t = t.replace(old_gate, new_gate)
p.write_text(t)
print('context.rs: eval closes the undefined-read question, doc line restored')
